$path = "Engine\Scene\GameScene.cs"
$content = Get-Content $path -Raw

# Fix 1: Reduce 3x multiplier to 1.5x and fix Y snapping
$old1 = "box.Physics.Velocity.X += nx * push * 3f;`r`n                        box.Physics.Velocity.Z += nz * push * 3f;`r`n                        playerPushed = true;`r`n                    }`r`n`r`n                    // Spheres vs player"
$new1 = "box.Physics.Velocity.X += nx * push * 1.5f;`r`n                        box.Physics.Velocity.Z += nz * push * 1.5f;`r`n                        playerPushed = true;`r`n                    }`r`n`r`n                    // Spheres vs player"

# Fix 2: Reduce 3x multiplier for spheres
$old2 = "sphere.Physics.Velocity.X += nx * push * 3f;`r`n                        sphere.Physics.Velocity.Z += nz * push * 3f;`r`n                        playerPushed = true;"
$new2 = "sphere.Physics.Velocity.X += nx * push * 1.5f;`r`n                        sphere.Physics.Velocity.Z += nz * push * 1.5f;`r`n                        playerPushed = true;"

# Fix 3: Fix Y snapping - use existing pattern
$old3 = "if (playerPushed)`r`n                    {`r`n                        float terrainY = _gameTerrainChunk.GetHeightAt(pPos.X, pPos.Z);`r`n                        pPos.Y = terrainY;`r`n                    }`r`n                    playerAgent.Position = pPos;`r`n                }`r`n`r`n                //  COLLISION: push NPC out of static objects (always runs) `r`n                var allObjs = _objectManager.GetObjects();"
$new3 = "if (playerPushed)`r`n                    {`r`n                        float terrainY = _gameTerrainChunk.GetHeightAt(pPos.X, pPos.Z);`r`n                        if (pPos.Y <= terrainY + 0.01f) pPos.Y = terrainY;`r`n                    }`r`n                    playerAgent.Position = pPos;`r`n                }`r`n`r`n                //  COLLISION: push NPC out of static objects (always runs) `r`n                var allObjs = _objectManager.GetObjects();"

$content = $content.Replace($old1, $new1)
$content = $content.Replace($old2, $new2)
$content = $content.Replace($old3, $new3)

# Fix 4: Add NPC vs physics objects collision after NPC static collision block
# Find the section after NPC static collision and add physics objects vs NPC collision
$old4 = "                //  COLLISION: player vs AI characters (capsule vs capsule) `r`n                {`r`n                    var pAgent"
$new4 = "                //  COLLISION: physics objects vs NPC characters (push them apart)`r`n                for (int oi = 0; oi < allObjs.Count; oi++)`r`n                {`r`n                    if (allObjs[oi].IsPlayer) continue;`r`n                    var npcPos2 = allObjs[oi].Position;`r`n                    float npcRad = CharacterAgent.CollisionRadius;`r`n                    float nSegMin = npcPos2.Y + npcRad;`r`n                    float nSegMax = npcPos2.Y + CharacterAgent.CapsuleHeight - npcRad;`r`n`r`n                    // Boxes vs NPC`r`n                    for (int bi = 0; bi < _physicsBoxes.Count; bi++)`r`n                    {`r`n                        var box = _physicsBoxes[bi];`r`n                        if (!box.Active) continue;`r`n`r`n                        float closestX = Math.Clamp(npcPos2.X, box.Position.X - box.HalfWidth, box.Position.X + box.HalfWidth);`r`n                        float closestZ = Math.Clamp(npcPos2.Z, box.Position.Z - box.HalfDepth, box.Position.Z + box.HalfDepth);`r`n                        float dx = npcPos2.X - closestX;`r`n                        float dz = npcPos2.Z - closestZ;`r`n                        float distSq = dx * dx + dz * dz;`r`n`r`n                        float boxMinY = box.Position.Y - box.HalfHeight;`r`n                        float boxMaxY = box.Position.Y + box.HalfHeight;`r`n                        float overlapY = MathF.Min(nSegMax, boxMaxY) - MathF.Max(nSegMin, boxMinY);`r`n                        if (overlapY <= 0.001f) continue;`r`n`r`n                        float minDist = npcRad;`r`n                        if (distSq >= minDist * minDist) continue;`r`n`r`n                        float dist = MathF.Sqrt(distSq);`r`n                        float nx, nz;`r`n                        if (dist > 1e-4f) { nx = dx / dist; nz = dz / dist; }`r`n                        else { nx = 1f; nz = 0f; }`r`n`r`n                        float push = (minDist - dist) * 0.5f;`r`n                        npcPos2.X += nx * push;`r`n                        npcPos2.Z += nz * push;`r`n                        box.Position.X -= nx * push;`r`n                        box.Position.Z -= nz * push;`r`n                        box.Object3D?.SetPosition(box.Position.X, box.Position.Y, box.Position.Z);`r`n                        box.Physics.Velocity.X += nx * push * 1.5f;`r`n                        box.Physics.Velocity.Z += nz * push * 1.5f;`r`n                    }`r`n`r`n                    // Spheres vs NPC`r`n                    for (int si = 0; si < _physicsSpheres.Count; si++)`r`n                    {`r`n                        var sphere = _physicsSpheres[si];`r`n                        if (!sphere.Active) continue;`r`n`r`n                        float dx = npcPos2.X - sphere.Position.X;`r`n                        float dz = npcPos2.Z - sphere.Position.Z;`r`n                        float distSq = dx * dx + dz * dz;`r`n`r`n                        float sphereMaxY = sphere.Position.Y + sphere.Radius;`r`n                        float sphereMinY = sphere.Position.Y - sphere.Radius;`r`n                        float overlapY = MathF.Min(nSegMax, sphereMaxY) - MathF.Max(nSegMin, sphereMinY);`r`n                        if (overlapY <= 0.001f) continue;`r`n`r`n                        float minDist = npcRad + sphere.Radius;`r`n                        if (distSq >= minDist * minDist) continue;`r`n`r`n                        float dist = MathF.Sqrt(distSq);`r`n                        float nx, nz;`r`n                        if (dist > 1e-4f) { nx = dx / dist; nz = dz / dist; }`r`n                        else { nx = 1f; nz = 0f; }`r`n`r`n                        float push = (minDist - dist) * 0.5f;`r`n                        npcPos2.X += nx * push;`r`n                        npcPos2.Z += nz * push;`r`n                        sphere.Position.X -= nx * push;`r`n                        sphere.Position.Z -= nz * push;`r`n                        sphere.Object3D?.SetPosition(sphere.Position.X, sphere.Position.Y, sphere.Position.Z);`r`n                        sphere.Physics.Velocity.X += nx * push * 1.5f;`r`n                        sphere.Physics.Velocity.Z += nz * push * 1.5f;`r`n                    }`r`n`r`n                    float terrainY2 = _gameTerrainChunk.GetHeightAt(npcPos2.X, npcPos2.Z);`r`n                    if (npcPos2.Y <= terrainY2 + 0.01f) npcPos2.Y = terrainY2;`r`n                    allObjs[oi].Position = npcPos2;`r`n                }`r`n`r`n                //  COLLISION: player vs AI characters (capsule vs capsule) `r`n                {`r`n                    var pAgent"

$content = $content.Replace($old4, $new4)

if ($content -eq (Get-Content $path -Raw)) {
    Write-Host "ERROR: No changes were made!"
    exit 1
}

Set-Content -Path $path -Value $content -NoNewline
Write-Host "SUCCESS: All fixes applied!"
